/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 08 Feb 2022 by chaminda
/// </summary>
/// <param name="sender"> Get form data source object</param>
/// <param name="e"> Get form data source args</param>
[FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::Activated),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
]
public static void PurchLine_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{      
    METPurchTableFormEventHandler::manageLocking(sender.formRun());        
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 01 Mar 2022 by chaminda
/// </summary>    
/// <param name="_formRun"> Get form run object </param>
private static void manageLocking(FormRun _formRun)
{
    SysGlobalObjectCache    cache;
    GlobalObjectCacheScope  cacheScope="@MET:PoRestrictionCache";
    container               cacheResult;
    cache                       = new SysGlobalObjectCache();
    FormDataSource datasource   = _formRun.dataSource(formDataSourceStr(PurchTable,PurchLine));        
    PurchLine purchLine = datasource.cursor();
    cacheResult         = cache.find(cacheScope,[purchLine.ItemId+curUserId()]);
    if(cacheResult == conNull())
    {
        METPurchTableFormEventHandler::controlElements(_formRun.dataSource(),METPurchTableFormEventHandler::checkConditionsToUnlockControls(_formRun));
    }
    else
    {
        METPurchTableFormEventHandler::controlElements(_formRun.dataSource(),conPeek(cacheResult,1));
    }
    
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 07 Feb 2022 by chaminda
/// </summary>
/// <returns>
/// A boolean value
/// </returns>
/// <param name="_formRun"> Get form run object </param>
private static NoYes checkConditionsToUnlockControls(FormRun _formRun)
{
    boolean         lock;
    VendParameters  vendParameters;        
    PurchLine       purchLine;
    ;
    FormDataSource datasource                = _formRun.dataSource(formDataSourceStr(PurchTable,PurchLine));
    PurchLine=datasource.cursor();        
    vendParameters  = VendParameters::find();
    if (PurchLine || purchLine.ItemId) // full record or unsaved record
    {
               
        if(vendParameters.METEnablePOCostUpdateRestrictions)
        {               
            if(METPurchTableFormEventHandler::checkUserExceptionDefined())
            {
                lock=false;                
            }
            else
            {
                if(!METPurchTableFormEventHandler::isProductCategoryDefinedOnPurchLineItem(purchLine.ItemId))
                {
                    lock=false;
                }
                else
                {
                    if(METPurchTableFormEventHandler::isProductCategoryinExceptionRule(purchLine.ItemId))
                    {
                        lock=false;
                    }
                    else
                    {
                        lock=true;
                    }                            
                }
            } 
        }
    }
    return lock;
}

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 07 Feb 2022 by chaminda
    /// </summary>
    /// <returns>
    /// A boolean value
    /// </returns>
    private static NoYes checkUserExceptionDefined()
    {
        
        SecurityUserRole                    securityUserRole;
        UserInfo                            userInfo;
        SecurityRole                        securityRole;
        METPOCostUpdateExceptionUserRoles   metPOCostUpdateExceptionUserRoles;
        boolean                             securityRoleFound;
       
        
        while select securityRole
            exists join securityUserRole
                where securityUserRole.SecurityRole == securityRole.RecId
            exists join userInfo
                where userInfo.id == securityUserRole.User
                &&    userInfo.id == curUserId()
        {
            metPOCostUpdateExceptionUserRoles=METPOCostUpdateExceptionUserRoles::find(securityRole.Name);
            if(metPOCostUpdateExceptionUserRoles)
            {
                securityRoleFound=NoYes::Yes;
                break;
            }
        }       

        return securityRoleFound;
    }

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 08 Feb 2022 by chaminda
/// </summary>
/// <param name="_itemId"> Get item id </param>
/// <returns>
/// A boolean value
/// </returns>
private static NoYes isProductCategoryDefinedOnPurchLineItem(ItemId _itemId)
{
    EcoResProductCategory   ecoResProductCategory;       
    select firstonly ecoResProductCategory
        where ecoResProductCategory.Product == InventTable::find(_itemId).Product;
    if(ecoResProductCategory)
    {
        return true;
    }
    else
    {
        return false;
    }
    
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 08 Feb 2022 by chaminda
/// </summary>
/// <param name="_itemId"> Get item id</param>
/// <returns>
/// A boolean value
/// </returns>
private static NoYes isProductCategoryinExceptionRule(ItemId _itemId)
{
    EcoResProductCategory   ecoResProductCategory;        
    boolean                 productCategoryListed;
    EcoResCategory          ecoResCategory;
    EcoResCategoryId        parentCategory;
    ;
    while select EcoResProductCategory
        join ecoResCategory
        where ecoResCategory.RecId == EcoResProductCategory.Category
        && EcoResProductCategory.Product == InventTable::find(_itemId).Product
    {
        if(METPOCostUpdateExceptionRules::find(ecoResProductCategory.CategoryHierarchy,ecoResCategory.RecId))
        {
            productCategoryListed=true;
        
        }
        else
        {
            parentCategory = ecoResCategory.ParentCategory;
            while (parentCategory)
            {
                if(METPOCostUpdateExceptionRules::find(ecoResProductCategory.CategoryHierarchy,parentCategory))
                {
                    productCategoryListed=true;
                    break;
                }
                select firstonly EcoResCategory
                    where EcoResCategory.RecId == parentCategory;
                parentCategory = EcoResCategory.ParentCategory;
            
        
            }   
        } 
    }
    
    return productCategoryListed;
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 10 Feb 2022 by chaminda
/// </summary>
/// <param name="_formDataSource"> Get form data source object object </param>
/// <param name="_lock"> get boolean value to change objects enabled property </param>

private static void controlElements(FormDataSource _formDataSource, NoYesId _lock)
{
    SysGlobalObjectCache    cache = new SysGlobalObjectCache();
    GlobalObjectCacheScope  cacheScope="@MET:PoRestrictionCache";
    container               cacheResult;                   
    FormRun                 formRun        = _formDataSource.formRun();
    FormDataSource          datasource     = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine));
    PurchLine purchLine = datasource.cursor();
    cacheResult         = cache.find(cacheScope,[PurchLine.ItemId+curUserId()]);
    if(cacheResult == conNull())
    {
        cache.insert(cacheScope,[PurchLine.ItemId+curUserId()],[_lock]);
    }
    datasource.object(fieldNum(PurchLine,LineAmount)).enabled(!_lock);
    datasource.object(fieldNum(PurchLine,PurchPrice)).enabled(!_lock);
}

