/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 01 Mar 2022 by chaminda
/// </summary>
/// <param name="sender"> Get form data object </param>
/// <param name="e"> source argsGet form data  </param>
[FormDataFieldEventHandler(formDataFieldStr(PurchTable, PurchLine, ItemId), FormDataFieldEventType::Modified),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
]
public static void ItemId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    METPurchTableFormEventHandler::manageLocking(sender.datasource().formRun());
    
}

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 15 Feb 2022 by chaminda
    /// </summary>
    /// <param name="_sender"> Get form run object </param>    
    private static void checkCostOverride(FormDataObject _sender)
    {
        FormDataSource  formDataSource  = _sender.datasource();
        PurchLine       purchLine       = formDataSource.cursor();
        VendParameters  vendParameters  = VendParameters::find();
        DictTable       dt = new SysDictTable(tableNum(PurchLine));
        DictField       dictField;
        if(purchLine && vendParameters.METEnablePOCostUpdateRestrictions)
        {
            PurchLine purchLineOrig = purchLine.orig();
            if(PurchLine)
            {
                if(purchLine.LineAmount != purchLineOrig.LineAmount)
                {
                    if(((purchLine.LineAmount-purchLineOrig.LineAmount)/purchLineOrig.LineAmount)*100 > vendParameters.METPOCostChangePercentAllowed)
                    {                   
                    
                        if(purchLine.PurchPrice != purchLineOrig.PurchPrice)
                        {                        
                            dictField   = dt.fieldObject(fieldNum(PurchLine,PurchPrice));                  
                            warning(strFmt("@MET:POCostOverrideWarning",vendParameters.METPOCostChangePercentAllowed,dictField.label(), purchLine.ItemId));                        
                        }
                        if(purchLine.LineAmount != purchLineOrig.LineAmount)
                        {
                            dictField   = dt.fieldObject(fieldNum(PurchLine,LineAmount));
                            warning(strFmt("@MET:POCostOverrideWarning",vendParameters.METPOCostChangePercentAllowed,dictField.label(), purchLine.ItemId));
                        }
                    }
                }
            }
        }

    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields on 30 Mar 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get form control object</param>
    /// <param name="e"> Get form data source args</param>
   
    [FormControlEventHandler(formControlStr(PurchTable, METPurchTable_POSubMode), FormControlEventType::Lookup),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METPurchTable_POSubMode_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        Args                                args;
        FormRun                             formRun;
        #Characters
        SysLookupMultiSelectValues          delimitedControlValues;
        SysDictEnum                         sysDictEnum = new SysDictEnum(enumNum(METPOSubMode));
        FormControlCancelableSuperEventArgs event       = e as FormControlCancelableSuperEventArgs;
        FormStringControl                   formStringControl = sender.formRun().design().controlName(formControlStr(PurchTable, METPurchTable_POSubMode));

        args = new args(formStr(METEnumLookup));
        args.parm(sysDictEnum.name());
        args.caller(formStringControl);
        formRun = classFactory.formRunClass(args);
        formRun.init();
        formStringControl.performFormLookup(formRun);
        FormDataSource                      metPurchTable_ds,metMultiSelectBaseEnumTable_ds ;
        metMultiSelectBaseEnumTable_ds = formRun.dataSource();
        metPurchTable_ds                 =sender.formRun().dataSource(formDataSourceStr(PurchTable, METPurchTable));
        METPurchTable metPurchTableLocal;
        metPurchTableLocal              = metPurchTable_ds.cursor();
        delimitedControlValues          = metPurchTableLocal.POSubMode;
        container controlValues         = str2con(delimitedControlValues, #Semicolon, false);
        if(!delimitedControlValues)
        {
            delimitedControlValues      = formStringControl.text();
        }
        if(!delimitedControlValues)
        {
            
            METMultiSelectBaseEnumTable metMultiSelectBaseEnumTableValues;
            while select EnumText from  metMultiSelectBaseEnumTableValues
                where metMultiSelectBaseEnumTableValues.EnumName == sysDictEnum.name()
            {
                delimitedControlValues += metMultiSelectBaseEnumTableValues.EnumText+#Semicolon;
            }          
        }
        if(delimitedControlValues)
        {
            int         counter, conLength;
            conLength   = conLen(controlValues);
            for (counter = 1; counter <= conLength; counter++)
            {
                METMultiSelectBaseEnumTable  metMultiSelectBaseEnumTable;
                select metMultiSelectBaseEnumTable
                    where metMultiSelectBaseEnumTable.EnumText == conpeek(controlValues, counter);
                metMultiSelectBaseEnumTable_ds.findRecord(metMultiSelectBaseEnumTable);
                metMultiSelectBaseEnumTable_ds.mark(true);
              
            }
        }
        
       
        formRun.wait();
        str store;
        METMultiSelectBaseEnumTable metMultiSelectBaseEnumTable;
        for (metMultiSelectBaseEnumTable = metMultiSelectBaseEnumTable_ds.getFirst(true) ? metMultiSelectBaseEnumTable_ds.getFirst(true) : metMultiSelectBaseEnumTable_ds.cursor();metMultiSelectBaseEnumTable;
        metMultiSelectBaseEnumTable = metMultiSelectBaseEnumTable_ds.getNext())
        {
            
            store += metMultiSelectBaseEnumTable.EnumText+#Semicolon;
               
        }
        store = subStr(store,1,strLen(store)-1);
        controlValues = str2con(store, #Semicolon, false);
             
        metPurchTable_ds=sender.formRun().dataSource(formDataSourceStr(PurchTable, METPurchTable));
        METPurchTable metPurchTable;
        metPurchTable=metPurchTable_ds.cursor();
        metPurchTable.POSubMode=store;
        metPurchTable.write();
        metPurchTable_ds.reread();
       
        event.CancelSuperCall();
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, METPurchTable), FormDataSourceEventType::ValidatingWrite)]
    public static void METPurchTable_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun                 formRun        = sender.formRun();
        METPurchTable           METPurchTable = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();
        FormDataSource          purchTabledatasource = formRun.dataSource(formDataSourceStr(PurchTable,purchTable));
        purchTable              purchTable = purchTabledatasource.cursor();

        if(purchTable.recid && !METPurchTable.PurchTable)
        {
            PurchTable.packMETPurchTable(METPurchTable);
            METPurchTable.SysExtensionSerializerExtensionMap::insertAfterBaseTable(PurchTable);
            METPurchTable.initFromVendSiteSettingsSetup();
        }
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::Writing)]
    public static void PurchLine_OnWritting(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun             formRun         = sender.formRun();
        PurchLine           purchLine       = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();

        METPurchTable       METPurchTable   = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(METPurchTable.POPromotionIHG)
        {
            purchLine.METPOLinePromotionIHG = METPurchTable.POPromotionIHG;
        }

    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::ValidatingWrite)]
    public static void PurchLine_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        var             args        = e as FormDataSourceCancelEventArgs;
        FormRun         formRun     = sender.formRun();
        PurchLine       purchLine   = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();

        METPurchTable   METPurchTable = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(args != null && METPurchTable.POPromotionIHG && !purchLine.METPOLinePromotionIHG)
        {
            Valid ret = checkFailed("Not all lines are marked ‘Yes’ as an IHG Promotion");
            args.cancel(ret);
        }
    }
